import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Work and labour rights","description":"Contracts, hours, leave, wages, changing employers, leaving Qatar and how to raise a complaint, for private-sector workers.","frontmatter":{"title":"Work and labour rights","description":"Contracts, hours, leave, wages, changing employers, leaving Qatar and how to raise a complaint, for private-sector workers.","lastChecked":"2026-10","sourceCount":2},"headers":[],"relativePath":"guide/work-and-labour-rights.md","filePath":"guide/work-and-labour-rights.md"}'),s={name:"guide/work-and-labour-rights.md"};function n(f,e,i,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="work-and-labour-rights" tabindex="-1">Work and labour rights <a class="header-anchor" href="#work-and-labour-rights" aria-label="Permalink to &quot;Work and labour rights&quot;">​</a></h1><p>This page covers the basic rights of people working for private employers in Qatar. It does not apply to public-sector employees, the armed forces or people working at sea, and domestic workers have some separate rules.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><p>Almost everything here comes from the National Human Rights Committee&#39;s Worker&#39;s Pocket Booklet, sixth edition, December 2021. It is a plain-language summary, not the law itself, and it tells readers to watch for later changes and to check the minimum wage with the Ministry of Labour. Treat the figures below as a starting point and confirm anything important with the Ministry.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="your-contract" tabindex="-1">Your contract <a class="header-anchor" href="#your-contract" aria-label="Permalink to &quot;Your contract&quot;">​</a></h2><ul><li>You need a written contract signed by you and your employer. Working without one is against the law.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>The contract should state the employer&#39;s name and place of work, your details, the type of work, the start date, the length of the contract if it is fixed, and the agreed wage with how and when it is paid.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>Keep a copy. If you were not given one, you can complain to the Labour Relations Department at the Ministry of Labour.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>A fixed-term contract cannot be longer than five years, and it can be renewed by agreement.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li><li>Probation cannot be longer than six months, and the same employer can only put you on probation once.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></li><li>Recruitment offices in Qatar are not allowed to charge you recruitment fees or expenses.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li></ul><p>Your employer may not hold your passport unless you asked for that in writing, and it must be returned when you ask. If it is refused, you can complain to the police or the public prosecution.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></p><h2 id="hours-and-rest" tabindex="-1">Hours and rest <a class="header-anchor" href="#hours-and-rest" aria-label="Permalink to &quot;Hours and rest&quot;">​</a></h2><ul><li>Normal hours are eight a day, and six a day during Ramadan. Rest breaks do not count as working time.<sup class="footnote-ref"><a href="#fn1" id="fnref1:9">[1]</a></sup></li><li>With overtime, the total should not go above ten hours a day, apart from urgent cases such as preventing serious loss or dealing with an accident.<sup class="footnote-ref"><a href="#fn1" id="fnref1:10">[1]</a></sup></li><li>Overtime is paid at your basic wage plus at least 25 percent.<sup class="footnote-ref"><a href="#fn1" id="fnref1:11">[1]</a></sup></li><li>Work between 9 pm and 3 am is paid at your basic wage plus 50 percent, except for shift workers.<sup class="footnote-ref"><a href="#fn1" id="fnref1:12">[1]</a></sup></li><li>Friday is the normal weekly rest day, except for shift workers. If you work on it, you get your basic pay for the day plus another rest day, or your basic pay plus 150 percent.<sup class="footnote-ref"><a href="#fn1" id="fnref1:13">[1]</a></sup></li><li>You cannot be made to work more than two Fridays in a row, even if you agree to it.<sup class="footnote-ref"><a href="#fn1" id="fnref1:14">[1]</a></sup></li></ul><h2 id="leave" tabindex="-1">Leave <a class="header-anchor" href="#leave" aria-label="Permalink to &quot;Leave&quot;">​</a></h2><ul><li>Annual leave is three weeks a year if you have less than five years of service, and four weeks with five years or more. Part-years are worked out in proportion.<sup class="footnote-ref"><a href="#fn1" id="fnref1:15">[1]</a></sup></li><li>Your employer sets the dates based on the needs of the work and must pay you for the leave before you take it.<sup class="footnote-ref"><a href="#fn1" id="fnref1:16">[1]</a></sup></li><li>You cannot give up your right to annual leave. If your contract ends first, you must be paid for the days you are owed.<sup class="footnote-ref"><a href="#fn1" id="fnref1:17">[1]</a></sup></li><li>Sick leave starts only after three months in the job and needs a certificate from a doctor your employer approves.<sup class="footnote-ref"><a href="#fn1" id="fnref1:18">[1]</a></sup></li><li>The first two weeks of sick leave are on full pay, the next four weeks on half pay, and anything after that is unpaid.<sup class="footnote-ref"><a href="#fn1" id="fnref1:19">[1]</a></sup></li><li>Public holidays have their own rules, covered in <a href="./holidays-and-ramadan">Public holidays and Ramadan working hours</a>.<sup class="footnote-ref"><a href="#fn1" id="fnref1:20">[1]</a></sup></li></ul><h2 id="wages" tabindex="-1">Wages <a class="header-anchor" href="#wages" aria-label="Permalink to &quot;Wages&quot;">​</a></h2><ul><li>The Wage Protection System requires employers to pay wages into your account within seven days of the due date. A Ministry of Labour department monitors this.<sup class="footnote-ref"><a href="#fn1" id="fnref1:21">[1]</a></sup></li><li>The booklet gives the minimum wage as QAR 1,000 a month. If your employer does not provide adequate housing or food, it adds at least QAR 500 for housing and QAR 300 for food. Check the current amounts with the Ministry.<sup class="footnote-ref"><a href="#fn1" id="fnref1:22">[1]</a></sup></li></ul><h2 id="end-of-service-gratuity" tabindex="-1">End-of-service gratuity <a class="header-anchor" href="#end-of-service-gratuity" aria-label="Permalink to &quot;End-of-service gratuity&quot;">​</a></h2><p>You qualify after a full year of work or more, and it covers all your years of service. If you disagree with your employer about how many years count, you can complain to the Labour Relations Department.<sup class="footnote-ref"><a href="#fn1" id="fnref1:23">[1]</a></sup></p><p>The booklet does not give the amount for most private-sector workers, so this page leaves it out until it can be confirmed from the law text. For domestic workers, it says at least three weeks&#39; wage for each year of service.<sup class="footnote-ref"><a href="#fn1" id="fnref1:24">[1]</a></sup></p><h2 id="changing-employers" tabindex="-1">Changing employers <a class="header-anchor" href="#changing-employers" aria-label="Permalink to &quot;Changing employers&quot;">​</a></h2><p>You can apply to change employer before your contract ends, without a certificate of objection from your current employer.<sup class="footnote-ref"><a href="#fn1" id="fnref1:25">[1]</a></sup></p><ol><li>Tell your current employer through the Ministry of Labour&#39;s electronic notification system. This includes your documented contract and a letter from the new employer. Your residence permit must be valid, or within 90 days of expiry, unless it expired for reasons beyond your control.<sup class="footnote-ref"><a href="#fn1" id="fnref1:26">[1]</a></sup></li><li>Give notice: one month if you have worked there for two years or less, two months if longer.<sup class="footnote-ref"><a href="#fn1" id="fnref1:27">[1]</a></sup></li><li>When the Ministry approves by text message, the new employer completes the new contract on the Ministry&#39;s digital system.<sup class="footnote-ref"><a href="#fn1" id="fnref1:28">[1]</a></sup></li><li>The case then moves to the Ministry of Interior, and the new employer applies for your new Qatar ID through Metrash.<sup class="footnote-ref"><a href="#fn1" id="fnref1:29">[1]</a></sup></li></ol><p>The process is free for you, so do not pay anyone for it. If your employer is not meeting its legal duties, including paying your wages, you can change without notice, and you must file a complaint with the Labour Relations Department.<sup class="footnote-ref"><a href="#fn1" id="fnref1:30">[1]</a></sup></p><p>Check your contract for a non-competition clause. It can only apply if your work gives you access to clients or business secrets, and it cannot last more than one year.<sup class="footnote-ref"><a href="#fn1" id="fnref1:31">[1]</a></sup></p><h2 id="leaving-qatar" tabindex="-1">Leaving Qatar <a class="header-anchor" href="#leaving-qatar" aria-label="Permalink to &quot;Leaving Qatar&quot;">​</a></h2><ul><li>You can leave, for a short trip or for good, without your employer&#39;s permission. An employer can ask for prior approval only for named staff, up to 5 percent of its workforce, because of the nature of their work.<sup class="footnote-ref"><a href="#fn1" id="fnref1:32">[1]</a></sup></li><li>If you are stopped from leaving, you can go to the Expatriates Exit Grievances Committee, which must decide within three working days.<sup class="footnote-ref"><a href="#fn1" id="fnref1:33">[1]</a></sup></li><li>If your residence permit ends or is cancelled, you have 90 days to leave.<sup class="footnote-ref"><a href="#fn1" id="fnref1:34">[1]</a></sup></li><li>If you leave without working your notice, you may not get a work permit for one year from the date you left.<sup class="footnote-ref"><a href="#fn1" id="fnref1:35">[1]</a></sup></li><li>At the end of a contract, your employer must arrange and pay for your ticket home within two weeks. If you join another job first, that duty passes to the new employer.<sup class="footnote-ref"><a href="#fn1" id="fnref1:36">[1]</a></sup></li></ul><h2 id="how-to-raise-a-complaint" tabindex="-1">How to raise a complaint <a class="header-anchor" href="#how-to-raise-a-complaint" aria-label="Permalink to &quot;How to raise a complaint&quot;">​</a></h2><ol><li>Start inside the company, with your supervisors or the joint committee if there is one.<sup class="footnote-ref"><a href="#fn1" id="fnref1:37">[1]</a></sup></li><li>If that fails, go to the Labour Relations Department at the Ministry of Labour, which tries to settle the dispute within seven days.<sup class="footnote-ref"><a href="#fn1" id="fnref1:38">[1]</a></sup></li><li>If it is not settled, the department refers it to the Labour Disputes Settlement Committee within three working days. You cannot go straight to the committee.<sup class="footnote-ref"><a href="#fn1" id="fnref1:39">[1]</a></sup></li><li>The committee decides within three weeks of its first session. Either side can appeal to the Court of Appeal within fifteen days.<sup class="footnote-ref"><a href="#fn1" id="fnref1:40">[1]</a></sup></li></ol><p>If the authorities do not respond, the National Human Rights Committee offers free legal advice.<sup class="footnote-ref"><a href="#fn1" id="fnref1:41">[1]</a></sup> Its hotline is 8002222, and you can complain by email at <a href="mailto:c@nhrc.org.qa" target="_blank" rel="noreferrer">c@nhrc.org.qa</a>, by phone, by fax, in person or online.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><p>For a complaint, write clearly what happened, give your contact details, and attach a copy of your passport or visa along with any supporting documents. Qataris attach a copy of their ID card instead.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></p><p>See also: <a href="./residence-permit-and-qid">Residence permit and QID</a>, <a href="./metrash">Metrash</a>, <a href="./holidays-and-ramadan">Public holidays and Ramadan working hours</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>National Human Rights Committee, <a href="https://www.nhrc-qa.org/storage/publications/file_6666d6f57f82d_1718015733.pdf" target="_blank" rel="noreferrer">Worker&#39;s Pocket Booklet, sixth edition, December 2021</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:9" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:10" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:11" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:12" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:13" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:14" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:15" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:16" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:17" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:18" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:19" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:20" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:21" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:22" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:23" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:24" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:25" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:26" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:27" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:28" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:29" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:30" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:31" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:32" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:33" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:34" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:35" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:36" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:37" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:38" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:39" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:40" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:41" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>National Human Rights Committee, <a href="https://www.nhrc-qa.org/" target="_blank" rel="noreferrer">Home page, contact and complaints section</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',30)])])}const d=a(s,[["render",n]]);export{p as __pageData,d as default};
